    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """

    if not isinstance(fixity, dict):
        raise TypeError("Fixity must be a dictionary")

    if "manifest" not in fixity:
        raise KeyError("Missing manifest in fixity block")

    if not isinstance(manifest_files, list):
        raise TypeError("Manifest must be a list")

    for file in fixity["manifest"]:
        if file not in manifest_files:
            raise ValueError("File " + file + " not listed in manifest")

    for file in manifest_files:
        if file not in fixity["manifest"]:
            raise ValueError("File " + file + " missing from fixity block")

    if "__files" in fixity:
        if not isinstance(fixity["__files"], list):
            raise TypeError("Fixity__files must be a list")

        for file in fixity["__files"]:
            if file not in manifest_files:
                raise ValueError("File " + file + " not listed in manifest")

            if file not in fixity["manifest"]:
                raise ValueError("File " + file + " missing from fixity block")

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise TypeError("Fixity block must be a dictionary")

    for key in fixity.keys():
        if key not in manifest_files:
            raise KeyError(f"Fixity block cannot reference files that are not in the manifest: {key}")

        for algorithm in fixity[key].keys():
            try:
                checksum = fixity[key][algorithm]
            except KeyError:
                raise KeyError(f"Fixity block must contain a checksum for the {algorithm} algorithm: {fixity[key]}")

            if not isinstance(checksum, str):
                raise TypeError(f"Fixity checksum must be a string: {checksum}")

            if not checksum.isalnum():
                raise ValueError(f"Fixity checksum must be an alphanumeric string: {checksum}")

