def _extract_number_and_supplment_from_issue_element(issue):
    """
    Extract number and suppl from issue element.

    Examples of possible values:
    5 (suppl), 5 Suppl, 5 Suppl 1, 5 spe, 5 suppl, 5 suppl 1, 5 suppl. 1,
    25 Suppl 1, 2-5 suppl 1, 2spe, Spe, Supl. 1, Suppl, Suppl 12,
    s2, spe, spe 1, spe pr, spe2, spe.2, spepr, supp 1, supp5 1, suppl,
    suppl 1, suppl 5 pr, suppl 12, suppl 1-2, suppl. 1
    """

    if issue == "":
        return (None, None)

    # remove whitespace
    issue = issue.strip()

    # remove parentheses and space
    issue = issue.replace("(", "").replace(")", "").replace(" ", "")

    # handle case where issue is just a number
    if issue.isdigit():
        return (int(issue), None)

    # handle case where issue is a number with suppl
    if issue[0].isdigit():
        number = issue.split(" ")[0]
        supplement = " ".join(issue.split(" ")[1:])
        return (int(number), supplement)

    # handle case where issue is a number with abbreviation
    if issue.split(" ")[0] in ["s", "spe", "suppl"]:
        number = issue.split(" ")[1]
        return (int(number), issue.split(" ")[0])

    # handle case where issue is a number with supplement
    if " suppl" in issue:
        number = issue.split(" suppl")[0]
        supplement = issue.split(" suppl")[1]
        return (int(number), supplement)

    # handle case where issue is a number with supplement and abbreviation
    if "suppl" in issue:
        number = issue

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    new_args = []
    for arg in args:
        if isinstance(arg, And):
            if any(x in arg.values for x in new_args):
                new_args.append(arg)
        elif isinstance(arg, Or):
            if any(x not in arg.values for x in new_args):
                new_args.append(arg)
        else:
            new_args.append(arg)
    return new_args

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    # positive absorption
    if isinstance(args[1], BinaryOp) and args[1].op in ['|']:
        if args[1].left == args[0]:
            return args[1].left
        elif args[1].right == args[0]:
            return args[1].right
    # negative absorption
    elif isinstance(args[1], BinaryOp) and args[1].op in ['&']:
        if args[1].left == args[0]:
            if isinstance(args[1].right, UnaryOp) and args[1].right.op == '~':
                return args[1].left & args[1].right.expr
        elif args[1].right == args[0]:
            if isinstance(args[1].left, UnaryOp) and args[1].left.op == '~':
                return args[1].right & args[1].left.expr
    return args

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    if len(args) == 0:
        return []
    if len(args) == 1:
        return [args[0]]
    expr = args[0]
    and_expr = args[1]
    or_expr = args[2]
    not_expr = args[3]
    if expr == and_expr or expr == or_expr:
        return [expr]
    if expr == not_expr:
        if and_expr == or_expr:
            return [expr]
        else:
            return [expr, or_expr]
    else:
        if and_expr == not_expr:
            return [expr, and_expr]
        else:
            return [expr, or_expr]

