    """Render the given version pieces into the requested style."""
    if not isinstance(pieces, list):
        raise TypeError("Expected a list of pieces, got {0}".format(type(pieces)))
    for piece in pieces:
        if not isinstance(piece, VersionPiece):
            raise TypeError("Expected a list of VersionPiece, got {0}".format(type(piece)))
    if style not in self.SUPPORTED_STYLES:
        raise ValueError("Unsupported style: {0}".format(style))
    rendered_pieces = []
    for piece in pieces:
        if piece.value is None:
            continue
        if style == "plain":
            rendered_pieces.append(piece.value)
        elif style == "markdown":
            if not piece.marks:
                rendered_pieces.append(piece.value)
            else:
                rendered_pieces.append("**" + piece.value + "**")
        elif style == "html":
            if not piece.marks:
                rendered_pieces.append("<p>" + piece.value + "</p>")
            else:
                rendered_pieces.append("<p><strong>" + piece.value + "</strong></p>")
    return "".join(rendered_pieces)

