def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    # Recursively validate hierarchy from current node
    for child in self.children:
        num_objects += 1
        if child.validate_hierarchy(validate_objects, check_digests, show_warnings):
            good_objects += 1

    # Validate current node
    if validate_objects and self.object is not None:
        if not self.object.is_valid():
            if show_warnings:
                print(f"WARNING: Object {self.object.id} is not valid.")
            return num_objects, good_objects

    if check_digests and self.digest is not None:
        if not self.object.is_valid_digest(self.digest):
            if show_warnings:
                print(f"WARNING: Object {self.object.id} has invalid digest {self.digest}.")
            return num_objects, good_objects

    return num_objects, good_objects

