def deep_merge_nodes(nodes):
    """
    Deep merge nodes corresponding to repeated keys, with non-repeated keys taking precedence.

    :param nodes: A list of tuples ``(ScalarNode, MappingNode or other Node)``
    :return: A list of tuples ``(ScalarNode, MappingNode or other Node)``
    """
    # Create a dictionary to store results, with scalar nodes as keys
    results = {}

    for node in nodes:
        key_node, value_node = node

        # If the key is not already in the results, add it
        if key_node not in results:
            results[key_node] = value_node
        else:
            # If the key is already in the results, recurse into the value node
            # if it is a mapping node
            if isinstance(value_node, MappingNode):
                # Get the existing value node for this key
                existing_value_node = results[key_node]

                # If the existing value node is not a mapping node, use the new value node
                if not isinstance(existing_value_node, MappingNode):
                    results[key_node] = value_node
                else:
                    # Otherwise, deep merge the new value node with the existing value node
                    results[key_node] = deep_merge_nodes([(key_node, existing_value_node), (key_node, value_node)])

    return list(results.items())

def deep_merge_nodes(nodes):
    unique_nodes = set()
    merged_nodes = []
    for node in nodes:
        key, value = node
        if key in unique_nodes:
            # Find the corresponding node in the merged list
            merged_node = next(x for x in merged_nodes if x[0] == key)
            # If the value is a MappingNode, recursively merge the nodes
            if isinstance(value, MappingNode):
                merged_node[1] = deep_merge_nodes([
                    (subkey, subvalue)
                    for subkey, subvalue in value.value
                    if subkey not in unique_nodes
                ])
        else:
            merged_nodes.append(node)
            unique_nodes.add(key)
    return merged_nodes

