    """
    Given a sequence of arguments and a dict from subparser name to
    argparse.ArgumentParser instance, give each requested action's subparser
    a shot at parsing all arguments. This allows common arguments like
    "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to
    a parsed namespace of arguments, a list of remaining arguments not
    claimed by any subparser).
    """
    parsed_arguments = {}
    for subparser in subparsers:
        try:
            parsed_arguments[subparser.prog] = subparser.parse_args(unparsed_arguments)
        except ValueError:
            pass
    remaining_arguments = []
    for argument in unparsed_arguments:
        if all(argument not in parsed_arguments[subparser.prog] for subparser in subparsers):
            remaining_arguments.append(argument)
    return (parsed_arguments, remaining_arguments)

