    for subparser_name, subparser in subparsers.items():
        try:
            parsed_subparsers[subparser_name] = subparser.parse_args(unparsed_arguments)
        except ArgumentError:
            # If this subparser cannot parse the arguments, move on to the next one
            continue

    for argument in unparsed_arguments:
        matched_subparser = None
        for subparser_name, subparser in subparsers.items():
            if argument in subparser.unesparsed_arguments:
                # If this argument is known to the subparser, mark it as matched
                matched_subparser = subparser_name
                break

        if matched_subparser:
            # If the argument was matched to a subparser, add it to the parsed subparsers dict
            if subparser_name in parsed_subparsers:
                parsed_subparsers[subparser_name].add_argument(argument)
            else:
                parsed_subparsers[subparser_name] = subparser.parse_args([argument])
        else:
            # If the argument was not matched to any subparser, add it to the remaining arguments list
            remaining_arguments.append(argument)

    return (parsed_subparsers, remaining_arguments)

