def int_to_string(self, number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if padding is None:
        padding = len(alphabet) - 1
    if padding < 1 or padding > len(alphabet):
        raise ValueError("Invalid padding size")
    result = ""
    while number > 0:
        result = alphabet[number % len(alphabet)] + result
        number //= len(alphabet)
    if len(result) < padding:
        result = alphabet[0] * (padding - len(result)) + result
    return result

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not isinstance(number, int):
        raise TypeError("number must be an integer")

    if not isinstance(alphabet, list):
        raise TypeError("alphabet must be a list")

    if not all(isinstance(c, str) for c in alphabet):
        raise TypeError("alphabet must contain only strings")

    if len(alphabet) != len(set(alphabet)):
        raise ValueError("alphabet must not contain duplicates")

    if padding is not None:
        if not isinstance(padding, int):
            raise TypeError("padding must be an integer")

        if padding < 0:
            raise ValueError("padding must be non-negative")

        if len(alphabet) ** padding < number:
            raise ValueError("number is too large to represent with given alphabet and padding")

    symbol_counts = {s: 0 for s in alphabet}
    out_str = ""

    while number > 0:
        symbols = [(symbol_counts[s], s) for s in alphabet]
        symbols.sort()
        largest_symbol, symbol = symbols[-1]
        symbol_counts[symbol] += 1
        out_str = symbol + out_str

        number -= symbol_counts[symbol]

    if padding is not None:
        while len(out_str) < padding:
            out_str = alphabet[0] + out_str

    return out_str

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if number < 0:
        raise ValueError("Only non-negative numbers are allowed")

    if padding is not None and padding < 0:
        raise ValueError("Padding must be non-negative")

    base = len(alphabet)
    if number == 0:
        return alphabet[0]

    ret = ""
    while number > 0:
        ret = alphabet[number % base] + ret
        number //= base

    if padding is not None:
        remaining_padding = padding - len(ret)
        if remaining_padding > 0:
            ret = alphabet[0] * remaining_padding + ret

    return ret

