    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import re
    if platform == 'this':
        platform = os.name

    if platform == 'posix':
        pattern = r'''((?:
            [^\s"']+                 # Non-whitespace without quotes
            | "[^"]*"(?<!\\)         # Double-quoted string without a closing quote
            | '[^']*'(?<!\\)         # Single-quoted string without a closing quote
            )+
        )|(?:\S)'''                   # Non-whitespace
