        pattern = r'''((?:
            [^\s"']+                 # Non-whitespace without quotes
            | "[^"]*"(?<!\\)         # Double-quoted string without a closing quote
            | '[^']*'(?<!\\)         # Single-quoted string without a closing quote
            )+)
        '''

    return re.findall(pattern, s)

