        return self._scale
    else:
        try:
            other = float(other)
        except ValueError:
            raise ValueError("Rescale factor must be a number.")
        if other <= 0:
            raise ValueError("Rescale factor must be positive.")
        if self._scale == 0:
            raise LenaValueError("Cannot rescale a graph with unknown scale.")
        self._scale = other
        for coord in self.coords:
            coord.rescale(other)

