        }
    }

    return nodeinfo

def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    try:
        verify_element = ElementFactory.create(ElementFactory.ELEMENT_VERIFY_WITH_RELAYABLE_SIGNATURE)
        return verify_element.verify(public_key, doc, signature)
    except VerificationException:
        return False

def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    try:
        if not isinstance(doc, Document):
            raise ValueError("The 'doc' argument must be a FoLiA document")
        if not isinstance(signature, bytes):
            raise ValueError("The 'signature' argument must be a bytes-like object")
        if not isinstance(public_key, ec.EllipticCurvePublicKey):
            raise ValueError("The 'public_key' argument must be an instance of ec.EllipticCurvePublicKey")

        key_info = doc.signed_xml.getKeyInfo()
        if key_info is None:
            raise ValueError("No KeyInfo element found in the signature")

        unique_id = key_info.getUniqueId()
        if unique_id is None:
            raise ValueError("No UniqueId element found in the KeyInfo of the signature")

        for element in doc.find("*[@id='{}']".format(unique_id)):
            if element.tag == "KeyInfo":
                return public_key.verify(signature, element.text.encode())
            else:
                raise ValueError("No KeyInfo element found with the ID '{}'".format(unique_id))

    except Exception as e:
        raise ValueError("Failed to verify the signature: {}".format(str(e)))

def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    # Check for missing parameters
    if not public_key or not doc or not signature:
        raise ValueError("Missing one or more required parameters.")

    # Verify the digital signature
    try:
        public_key.verify_xml(xml_string=doc, signature=signature)
    except PyAsiceError as e:
        # Rapid error test,ei dhd e an expose interface for generic errors
        if e.error_code == "signature_invalid":
            raise MailvelopeError("Invalid signature")
        else:
            raise MailvelopeError(f"Unknown error: {e}")

    # Check for revoked status
    try:
        public_key.check_revoked()
    except PyAsiceError as e:
        raise MailvelopeError("Key is revoked.")

    return True

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        data = json.loads(document)
        return data
    except json.JSONDecodeError:
        # It seems the webfinger is in XRD format
        xrd = parse_xrd(document)
        data = {
            "subject": xrd.get("subject"),
            "aliases": xrd.get("aliases"),
            "links": []
        }
        for link in xrd.links:
            data["links"].append({
                "type": link.type,
                "href": link.href,
                "titles": []
