def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        data = json.loads(document)
        webfinger = {}
        webfinger['subject'] = data['subject']
        aliases = data.get('aliases', [])
        for alias in aliases:
            webfinger[alias] = data[alias]
        return webfinger
    except ValueError:
        # XRD format
        root = ET.fromstring(document)
        webfinger = {}
        for child in root:
            if child.tag == 'Subject':
                webfinger['subject'] = child.text
            elif child.tag == 'Alias':
                webfinger[child.attrib['href']] = child.text
        return webfinger

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    # Try to load the document as JSON
    try:
        data = json.loads(document)
    except json.JSONDecodeError:
        # If JSON parsing fails, try to load it as XRD
        try:
            data = XRD.parse(document).to_dict()
        except XRDError:
            # If both JSON and XRD parsing fail, return an empty dictionary
            return {}

    # Extract the key-value pairs from the parsed data
    results = {}
    for element in data:
        # Extract the key-value pairs from the <Link> elements
        if element.startswith("link"):
            key = element.get("rel")
            value = element.get("href")
            results[key] = value

    return results

