def retrieve_and_parse_diaspora_webfinger(self, handle):
        """
        Retrieve and parse a remote Diaspora webfinger document.

        :arg handle: Remote handle to retrieve
        :returns: dict
        """
        # Step 1: Retrieve the remote document
        import requests
        try:
            response = requests.get(handle, timeout=10)
            if response.status_code != 200:
                raise IOError("webfinger request failed, status code: {}".format(response.status_code))
        except requests.exceptions.RequestException as e:
            print("unable to retrieve webfinger document: {}".format(e))
            return {}

        # Step 2: Parse the webfinger document
        from lxml import etree
        try:
            doc = etree.fromstring(response.content)
        except etree.XMLSyntaxError as e:
            print("unable to parse webfinger document: {}".format(e))
            return {}

        # Step 3: Extract the relevant information
        information = {}
        for child in doc.findall("*"):
            tag = child.tag.split("}")[1]
            if tag in ["subject", "aliases", "links", "properties"]:
                continue
            information[tag] = child.text

        return information

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    import requests
    from requests.structures import CaseInsensitiveDict

    try:
        response = requests.get(handle, headers={"Accept": "application/json"})
        if response.status_code != 200:
            raise ValueError(
                f"Non-200 status code returned: {response.status_code}")
        webfinger = response.json()
    except requests.exceptions.SSLError as e:
        raise ValueError(f"Failed to establish SSL connection: {e}")
    except requests.exceptions.ConnectionError as e:
        raise ValueError(f"Failed to connect: {e}")
    except requests.exceptions.Timeout as e:
        raise ValueError(f"Connection timed out: {e}")
    except requests.exceptions.TooManyRedirects as e:
        raise ValueError(f"Too many redirects: {e}")
    except requests.exceptions.RequestException as e:
        raise ValueError(f"Request failed: {e}")
    except ValueError as e:
        raise ValueError(f"Failed to decode JSON: {e}")

    webfinger = CaseInsensitiveDict(webfinger)

    if "links" not in webfinger or len(webfinger["links"]) == 0:
        raise ValueError("Missing 'links' element in webfinger document")

    webfinger = {link["rel"]: link for link in webfinger["links"]}

    return webfinger

def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    try:
        response = requests.get('https://' + host + '/.well-known/host-meta.json')
        if response.status_code == 200:
            return XRD.parse(response.content)
        else:
            raise DiasporaError('Failed to retrieve host-meta from ' + host + ': ' + response.status_code)
    except requests.exceptions.RequestException as e:
        raise DiasporaError('Failed to retrieve host-meta from ' + host + ': ' + str(e))

