    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """

    if not spec_content:
        raise IRValidatorException("No spec content found")

    mandatory_keys = ["name", "kind", "code", "description"]
    for key in mandatory_keys:
        if key not in spec_content:
            raise IRValidatorException(f"Key {key} missing in spec content")

    return yaml.load(spec_content, Loader=yaml.FullLoader)

def validate_from_content(cls, spec_content=None):

    content = yaml.safe_load(spec_content)
    if content is None:
        raise IRValidatorException("Invalid YAML spec file")

    required_top_level_keys = {
        "schemaVersion",
        "name",
        "version",
        "tasks"
    }

    for key in required_top_level_keys:
        if key not in content:
            raise IRValidatorException(f"Missing top-level key: {key}")

    version = content["version"]
    if version not in SUPPORTED_VERSIONS:
        raise IRValidatorException(f"Unsupported version: {version}")

    tasks = content["tasks"]
    task_names = list(tasks.keys())

    for task_name in task_names:
        task = tasks[task_name]

        if "runtime" not in task:
            raise IRValidatorException(f"Missing required 'runtime' field for task: {task_name}")

        runtime = task["runtime"]

        if runtime not in SUPPORTED_RUNTIMES:
            raise IRValidatorException(f"Unsupported runtime: {runtime}")

        supported_versions = SUPPORTED_VERSIONS[runtime]

        if version not in supported_versions:
            raise IRValidatorException(f"Unsupported version for runtime {runtime}: {version}")

    return content

def validate_from_content(cls, spec_content=None):
        """validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data
        is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """

        # load spec file content as dictionary
        if spec_content:
            try:
                spec_dict = yaml.load(spec_content, Loader=yaml.FullLoader)
            except yaml.YAMLError as exc:
                raise exc

        # check for presence of required keys in spec_dict
        required_keys = ['schema', 'features']

        for key in required_keys:
            if key not in spec_dict:
                raise IRValidatorException(f"Missing mandatory key {key} in spec file")

        # check for empty values in required keys
        for key in required_keys:
            if not spec_dict[key]:
                raise IRValidatorException(f"Empty value for mandatory key {key} in spec file")

        # check for duplicate features
        if 'features' in spec_dict:
            features = spec_dict['features']
            feature_names = set()
            for feature in features:
                if feature['name'] in feature_names:
                    raise IRValidatorException(f"Duplicate feature name {feature['name']} in spec file")
                feature_names.add(feature['name'])

        # check for missing 'value' key in each feature
        for feature in features:
            if 'value' not in feature:
                raise IRValidatorException(f"Missing mandatory key 'value' for feature {feature['name']} in spec file")
            value = feature['value']
            if not value:
                raise IRValidatorException(f"Empty value for 'value' in feature {feature['name']} in spec file")

        # check for duplicate values in features
        if 'features' in spec_dict:
            features = spec_dict['features']
            for feature in features:
                if 'value' in feature:
                    value = feature

def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    try:
        with open(yaml_file, 'r') as fr:
            yaml_data = yaml.safe_load(fr)
            cls.validate_yaml_data(yaml_data)
        return yaml_data
    except IrValidatorException as e:
        raise e

def validate_yaml_data(cls, yaml_data):
    """Validates that a YAML data has all required fields

    :param yaml_data: YAML data
    :raise IRValidatorException: when mandatory data is missing
    """
    required_fields = cls.REQUIRED_FIELDS
    for field in required_fields:
        if field not in yaml_data:
            raise IRValidatorException(f"The field {field} is required in the YAML file but is missing.")
    optional_fields = cls.OPTIONAL_FIELDS
    for field in optional_fields:
        if field not in yaml_data:
            continue
        field_type = cls.FIELD_TYPES[field]
        value = yaml_data[field]
        if field_type == 'bool':
            if value.lower() not in ['true', 'false']:
                raise IRValidatorException(f"The value of field {field} should be a boolean (true/false), but got {value}.")
        if field_type == 'int':
            try:
                int(value)
            except ValueError:
                raise IRValidatorException(f"The value of field {field} should be an int, but got {value}.")
        if field_type == 'float':
            try:
                float(value)
            except ValueError:
                raise IRValidatorException(f"The value of field {field} should be a float, but got {value}.")

def validate_from_file(cls, yaml_file=None):
