        with open(yaml_file, 'r') as f:
            yaml_data = yaml.safe_load(f)
        if not yaml_data:
            raise IRValidatorException("Empty YAML file")
        cls.required_fields = ['service_type', 'service_name', 'host', 'port', 'protocol']
        for field in cls.required_fields:
            if field not in yaml_data:
                raise IRValidatorException("Missing mandatory field in YAML file: {}".format(field))
        return yaml_data
    except IOError as e:
        raise IRValidatorException("Error reading YAML file: {}".format(e))
    except yaml.YAMLError as e:
