    :param options_spec: the list of command spec options.
    :param args: the received input arguments
    :return: list of argument names with matched `required_when` condition
    """
    conditionally_required_args = []
    for option in options_spec:
        if option.required_when and option.name in args:
            if isinstance(option.required_when, str):
                if args[option.name] == option.required_when:
                    conditionally_required_args.append(option.name)
